/** Each operation's input and output. */
export interface Operations {
  /** Get the authenticated principal. Returns the principal and token that authenticated this request, and for a delegated token the agents acting for the principal. */
  "meta.whoami": { input: MetaWhoamiInput; output: MetaWhoamiOutput };
  /** List the platform's signing keys. The public keys Fyrden signs the commits it makes with (file writes, generated repositories), as SSH public key lines: the current one, and retired ones commits may still carry. Check such a commit with `git verify-commit` (`gpg.format = ssh`) and these keys in an allowed-signers file. */
  "meta.signing_keys.list": { input: MetaSigningKeysListInput; output: MetaSigningKeysListOutput };
  /** List your SSH signing keys. The SSH keys the authenticated user signs commits with, oldest first. */
  "users.ssh_signing_keys.list": { input: UsersSshSigningKeysListInput; output: UsersSshSigningKeysListOutput };
  /** Add an SSH signing key. Adds an Ed25519 SSH public key the authenticated user signs commits with (`gpg.format = ssh`). A commit with a valid signature by it is verified when its committer email is the user's no-reply address (`<user id>@users.noreply.<host>`). A key belongs to one user: one already added answers 422 `key_in_use`. */
  "users.ssh_signing_keys.create": { input: UsersSshSigningKeysCreateInput; output: UsersSshSigningKeysCreateOutput };
  /** Get an SSH signing key. One of the authenticated user's SSH signing keys. */
  "users.ssh_signing_keys.get": { input: UsersSshSigningKeysGetInput; output: UsersSshSigningKeysGetOutput };
  /** Delete an SSH signing key. Removes one of the authenticated user's SSH signing keys; commits it signed are no longer verified. */
  "users.ssh_signing_keys.delete": { input: UsersSshSigningKeysDeleteInput; output: UsersSshSigningKeysDeleteOutput };
  /** List your tokens. Your personal access and git tokens, newest first; revoked and expired ones too. */
  "users.tokens.list": { input: UsersTokensListInput; output: UsersTokensListOutput };
  /** Create a token. Mints a personal access token (`pat`) or a git token (`git`, for clone, fetch and push) for you, never wider than the token or session making it, and returns it once. */
  "users.tokens.create": { input: UsersTokensCreateInput; output: UsersTokensCreateOutput };
  /** Revoke a token. Revokes one of your tokens: it stops working at once for writes (within 30 seconds for reads). */
  "users.tokens.revoke": { input: UsersTokensRevokeInput; output: UsersTokensRevokeOutput };
  /** Create a user. Creates a user account. Instance administrators only. */
  "admin.users.create": { input: AdminUsersCreateInput; output: AdminUsersCreateOutput };
  /** Create a token for a user. Mints a personal access token (`pat`) or git token (`git`) for a user and returns it once. Instance administrators only. */
  "admin.tokens.create": { input: AdminTokensCreateInput; output: AdminTokensCreateOutput };
  /** Create an agent. Creates an agent principal owned by you, or by an organization you own (`org`). An agent acts with its own tokens and collaborator roles, or for a user under a delegation grant; either way it never exceeds its owner. */
  "agents.create": { input: AgentsCreateInput; output: AgentsCreateOutput };
  /** List agents. Your agents, or those of an organization you own (`org`), oldest first. */
  "agents.list": { input: AgentsListInput; output: AgentsListOutput };
  /** Get an agent. An agent you own, or one an organization you own owns. */
  "agents.get": { input: AgentsGetInput; output: AgentsGetOutput };
  /** Disable an agent. Disables an agent: its tokens, the tokens issued for it under delegation grants, and its grants stop working at once for writes (within 30 seconds for reads). Its handle stays taken. */
  "agents.disable": { input: AgentsDisableInput; output: AgentsDisableOutput };
  /** Create a token for an agent. Mints a token the agent acts with as itself: a personal access token (`pat`, also the subject of a token exchange) or a git token (`git`), never wider than your token (its scopes and repositories). Returned once. */
  "agents.tokens.create": { input: AgentsTokensCreateInput; output: AgentsTokensCreateOutput };
  /** List an agent's tokens. The tokens an agent acts with as itself (personal access and git tokens), newest first; revoked and expired ones too. Never the token values. */
  "agents.tokens.list": { input: AgentsTokensListInput; output: AgentsTokensListOutput };
  /** Revoke an agent's token. Revokes one of an agent's tokens: it stops working at once for writes (within 30 seconds for reads); the agent's other tokens keep working. */
  "agents.tokens.revoke": { input: AgentsTokensRevokeInput; output: AgentsTokensRevokeOutput };
  /** Create a delegation grant. Lets an agent act for you, limited to `scopes`, `repositories` and an expiry: the agent exchanges its own token for a delegated one (`POST /oauth/token`, RFC 8693). An agent holding a grant may pass a narrower one (`parent`) to another agent of its owner, one hop down at most. Revoking a grant revokes the tokens issued under it and its sub-grants. */
  "grants.create": { input: GrantsCreateInput; output: GrantsCreateOutput };
  /** List delegation grants. The grants you made (a user), or that you hold or passed down (an agent), newest first; revoked ones too. */
  "grants.list": { input: GrantsListInput; output: GrantsListOutput };
  /** Revoke a delegation grant. Revokes a grant and the grants passed down from it: every token issued under them stops working at once for writes (within 30 seconds for reads). Its user, or the agent that passed it down, may revoke it. */
  "grants.revoke": { input: GrantsRevokeInput; output: GrantsRevokeOutput };
  /** Create an organization. Creates an organization with a user as its first owner. Instance administrators only. */
  "admin.orgs.create": { input: AdminOrgsCreateInput; output: AdminOrgsCreateOutput };
  /** Update an organization's settings. Changes an organization's settings: whether its agents' API tokens must be DPoP-bound (`require_dpop`). Owners only. */
  "orgs.update": { input: OrgsUpdateInput; output: OrgsUpdateOutput };
  /** Create a repository. Creates an empty private repository owned by the authenticated user. Clone and push it at `/<owner>/<name>.git`. */
  "repos.create": { input: ReposCreateInput; output: ReposCreateOutput };
  /** List your repositories. Lists the repositories the authenticated principal owns and its token can see, by name (ignoring case). A repository created a moment ago is listed; its `default_branch` can lag behind a change by a few seconds (use `GET /repos/{owner}/{repo}` for the current one). */
  "repos.list": { input: ReposListInput; output: ReposListOutput };
  /** Get a repository. Returns a repository the caller can see. A repository that does not exist and one the caller cannot see both answer 404. */
  "repos.get": { input: ReposGetInput; output: ReposGetOutput };
  /** Update a repository. Renames a repository, changes its description or default branch, marks it as a template, or sets or clears its expiry; fields left out are kept. After a rename the old name keeps working for clone, fetch, push and this API, until a repository takes that name again. */
  "repos.update": { input: ReposUpdateInput; output: ReposUpdateOutput };
  /** Delete a repository. Deletes a repository: from now on it cannot be pushed or changed, and within about 30 seconds it can no longer be found or read under any name; its data, events and storage are then removed, and its audit records kept. Forks keep their own data. The name is free again once `state` is `deleted`. */
  "repos.delete": { input: ReposDeleteInput; output: ReposDeleteOutput };
  /** Delete several of your repositories. Deletes up to 100 repositories you own, by name, as `DELETE /repos/{owner}/{repo}` does for one. Each name answers `deleting`, `deleted` or `not_found` (no such repository, or the token cannot administer it). Deletions this request does not finish continue in the background. */
  "repos.delete_many": { input: ReposDeleteManyInput; output: ReposDeleteManyOutput };
  /** Transfer a repository. Moves a repository you administer to another account: yourself or an organization you may create repositories in, under its name or `new_name`. Its collaborators, rulesets, stars and history go with it; the old account's team grants stay behind. The old path keeps working as a redirect. While it moves (usually under a second), it takes no push or change. Answers 409 `name_taken` or 403 `quota_exceeded` when the new account cannot take it. */
  "repos.transfer": { input: ReposTransferInput; output: ReposTransferOutput };
  /** Fork a repository. Creates a fork of a repository the caller can read, owned by the caller, in the same fork network: it starts with the parent's branches, tags and default branch, and shares the parent's stored objects, so no data is copied. The fork can be cloned as soon as this returns. Answers 409 `network_busy` while the network's storage is being collected; retry after a few seconds. */
  "repos.fork": { input: ReposForkInput; output: ReposForkOutput };
  /** List forks. Lists the forks of a repository that the caller owns, oldest first. Forks owned by other accounts are not listed. */
  "repos.forks.list": { input: ReposForksListInput; output: ReposForksListOutput };
  /** Create a repository from a template. Creates a private repository whose first commit (on `main`) holds the files of the template's default branch, with their modes, symlinks and submodule links (at most 2,000 files and directories, 8 MiB in all). Unlike a fork it starts its own history and shares nothing with the template. The template must be marked `is_template` and readable by the caller; `owner` may be the caller or an organization it may create repositories in, where it can write. The token needs `contents:write` as well, without a repository list. Answers 422 `not_a_template`, or 422 `template_too_large` past the bounds; on a failure no repository is left. */
  "repos.generate": { input: ReposGenerateInput; output: ReposGenerateOutput };
  /** List rulesets. The repository's rulesets, by id. */
  "repos.rulesets.list": { input: ReposRulesetsListInput; output: ReposRulesetsListOutput };
  /** Get a ruleset. One of the repository's rulesets. */
  "repos.rulesets.get": { input: ReposRulesetsGetInput; output: ReposRulesetsGetOutput };
  /** Create a ruleset. Adds rules on the branches or tags whose names match: pushes, file writes and every other change of a matching ref are checked against them (refused ones are `ng`, naming the ruleset). Rules on names and kinds of change are checked before a push is stored; force pushes and signatures at its commit, with the rulesets current then. At most 50 per repository. Administrators only. */
  "repos.rulesets.create": { input: ReposRulesetsCreateInput; output: ReposRulesetsCreateOutput };
  /** Update a ruleset. Replaces a ruleset. Administrators only. */
  "repos.rulesets.update": { input: ReposRulesetsUpdateInput; output: ReposRulesetsUpdateOutput };
  /** Delete a ruleset. Removes a ruleset. Administrators only. */
  "repos.rulesets.delete": { input: ReposRulesetsDeleteInput; output: ReposRulesetsDeleteOutput };
  /** Star a repository. Stars a repository the caller can read. Starring one already starred changes nothing. The token also needs `metadata:read` for the repository. */
  "stars.put": { input: StarsPutInput; output: StarsPutOutput };
  /** Unstar a repository. Takes the caller's star off a repository it can read. Unstarring one not starred changes nothing. */
  "stars.delete": { input: StarsDeleteInput; output: StarsDeleteOutput };
  /** List starred repositories. Lists the repositories the caller starred, most recently starred first. Repositories the caller or its token can no longer read are left out, so a page can hold fewer than `per_page`; keep following `next_cursor` until it is null. */
  "stars.list": { input: StarsListInput; output: StarsListOutput };
  /** Get your quota. The authenticated user's quota: how many repositories it may have and how many bytes their pushes may store, and how much of each is used. A deleted repository's bytes are free again once its deletion finishes. */
  "quotas.user.get": { input: QuotasUserGetInput; output: QuotasUserGetOutput };
  /** Get an organization's quota. An organization's quota and its use, for its members. */
  "quotas.org.get": { input: QuotasOrgGetInput; output: QuotasOrgGetOutput };
  /** Set an account's quota. Sets a user's or organization's limits; null goes back to the instance default, and a limit left out is kept. Lowering a limit below the use refuses new repositories and pushes; nothing is deleted. Instance administrators only. */
  "admin.quotas.set": { input: AdminQuotasSetInput; output: AdminQuotasSetOutput };
  /** List branches. Lists a repository's branches by name, each with the commit it points to. */
  "repos.branches.list": { input: ReposBranchesListInput; output: ReposBranchesListOutput };
  /** Get a branch. A branch and its latest commit. Branch names may contain slashes. */
  "repos.branches.get": { input: ReposBranchesGetInput; output: ReposBranchesGetOutput };
  /** List tags. Lists a repository's tags by name, each with the commit it points to (annotated tags are peeled; tags of other objects are not listed). */
  "repos.tags.list": { input: ReposTagsListInput; output: ReposTagsListOutput };
  /** List commits. The history from a branch, tag or commit (the default branch without `sha`), newest first, as `git log` lists it (unless commit dates go backwards: the order is by corrected commit date); with `path`, only commits that change that file or directory. A page can hold fewer commits than `per_page` and still have a next one. */
  "repos.commits.list": { input: ReposCommitsListInput; output: ReposCommitsListOutput };
  /** Get a commit. One commit, named by its SHA or by a branch or tag. */
  "repos.commits.get": { input: ReposCommitsGetInput; output: ReposCommitsGetOutput };
  /** Compare two commits. Compares `base...head` (branches, tags or SHAs): how far head is ahead of and behind base, their merge base, and the commits in head and not in base, oldest first (the newest 100). File differences are not included. */
  "repos.compare": { input: ReposCompareInput; output: ReposCompareOutput };
  /** List the repository's root directory. The root directory's entries at a branch, tag or commit, a page at a time. */
  "repos.contents.root": { input: ReposContentsRootInput; output: ReposContentsRootOutput };
  /** Get repository content. What a path names at a branch, tag or commit: a directory's entries (in git's order, a page at a time), a file and its content (base64, up to 1 MiB; larger files have `encoding: none` and are read through `download_url`), a symlink and its target, or a submodule and its commit. */
  "repos.contents.get": { input: ReposContentsGetInput; output: ReposContentsGetOutput };
  /** Get the README. The README file in the root directory at a branch, tag or commit (`README.md` first, then other README files). */
  "repos.readme.get": { input: ReposReadmeGetInput; output: ReposReadmeGetOutput };
  /** Get a tree. The root tree of a branch, tag or commit (`tree_sha` names one of them: a bare tree SHA is not accepted), with `recursive` every file and directory below it, as `git ls-tree -r -t` lists them. A listing of more than 10,000 entries, or of more trees than one request may read, is `truncated`. */
  "repos.trees.get": { input: ReposTreesGetInput; output: ReposTreesGetOutput };
  /** Get an archive link. Prepares the files of a branch, tag or commit as a tar.gz or zip archive and gives its link (`download_url`, GitHub's tarball or zipball route; the same token works). A large archive is built in the background: `state` is `building` until it is `ready`; ask again, or fetch the link, which answers 202 until then. Archives hold 1 GiB of files at most, each file 24 MiB at most, a zip 65,535 entries. */
  "repos.archives.get": { input: ReposArchivesGetInput; output: ReposArchivesGetOutput };
  /** Create or update a file. Writes one file as a new commit on a branch (GitHub's contents API). To update a file, give its current blob `sha`; without `sha` the file must not exist yet. Fails with 409 when the file or the branch changed meanwhile. */
  "repos.contents.put": { input: ReposContentsPutInput; output: ReposContentsPutOutput };
  /** Delete a file. Deletes one file as a new commit on a branch. `sha` is the file's current blob SHA; fails with 409 when the file or the branch changed meanwhile. */
  "repos.contents.delete": { input: ReposContentsDeleteInput; output: ReposContentsDeleteOutput };
  /** Commit changes to several files. Writes and deletes up to 100 files (4 MiB of content together) as one commit on a branch. With `expected_head`, fails with 409 unless the branch is still at that commit; the commit is always made on the head it was built on, so a branch that moves meanwhile also fails with 409. */
  "repos.file_commits.create": { input: ReposFileCommitsCreateInput; output: ReposFileCommitsCreateOutput };
  /** Add a member or change a member's role. Makes a user a member (or an owner, `admin`) of an organization, at once. The last owner cannot be made a member. Owners only. */
  "orgs.memberships.set": { input: OrgsMembershipsSetInput; output: OrgsMembershipsSetOutput };
  /** Remove a member. Removes a user from an organization and its teams; collaborator roles on its repositories stay. Repositories told of the change stop counting the membership at once; every repository stops within 60 seconds for writes and 5 minutes for reads. The last owner cannot be removed. Owners only. */
  "orgs.memberships.remove": { input: OrgsMembershipsRemoveInput; output: OrgsMembershipsRemoveOutput };
  /** List an organization's members. Lists an organization's members by handle, ignoring case. Members only. */
  "orgs.members.list": { input: OrgsMembersListInput; output: OrgsMembersListOutput };
  /** Create an organization repository. Creates an empty private repository owned by an organization. Members may create them; owners administer every repository of the organization, and members can read them. */
  "orgs.repos.create": { input: OrgsReposCreateInput; output: OrgsReposCreateOutput };
  /** List an organization's repositories. Lists an organization's repositories, by name (ignoring case), for its members. A repository created a moment ago is listed; its `default_branch` can lag behind a change by a few seconds. */
  "orgs.repos.list": { input: OrgsReposListInput; output: OrgsReposListOutput };
  /** Add a collaborator or change a collaborator's role. Gives a user a role on one repository, at once (no invitation). Administrators of the repository only. */
  "repos.collaborators.set": { input: ReposCollaboratorsSetInput; output: ReposCollaboratorsSetOutput };
  /** Remove a collaborator. Takes a user's collaborator role on a repository away; roles the user has otherwise (organization, teams) stay. Repositories told of the change stop counting it at once; every repository stops within 60 seconds for writes and 5 minutes for reads. Administrators of the repository only. */
  "repos.collaborators.remove": { input: ReposCollaboratorsRemoveInput; output: ReposCollaboratorsRemoveOutput };
  /** List a repository's collaborators. Lists the users given a role on this repository directly, by handle (owners, organization members and teams are not listed). */
  "repos.collaborators.list": { input: ReposCollaboratorsListInput; output: ReposCollaboratorsListOutput };
  /** Create a team. Creates a team in an organization, with no members or repositories; its slug comes from its name. Owners only. */
  "orgs.teams.create": { input: OrgsTeamsCreateInput; output: OrgsTeamsCreateOutput };
  /** List an organization's teams. Lists an organization's teams by slug. Members only. */
  "orgs.teams.list": { input: OrgsTeamsListInput; output: OrgsTeamsListOutput };
  /** Add a team member. Adds a member of the organization to a team, at once. Owners only. */
  "orgs.teams.memberships.set": { input: OrgsTeamsMembershipsSetInput; output: OrgsTeamsMembershipsSetOutput };
  /** Remove a team member. Removes a user from a team; roles the user has otherwise stay. Repositories told of the change stop counting the team's role at once; every repository stops within 60 seconds for writes and 5 minutes for reads. Owners only. */
  "orgs.teams.memberships.remove": { input: OrgsTeamsMembershipsRemoveInput; output: OrgsTeamsMembershipsRemoveOutput };
  /** Give a team a role on a repository. Gives a team a role on one of the organization's repositories; every member of the team gets it. Owners only. */
  "orgs.teams.repos.set": { input: OrgsTeamsReposSetInput; output: OrgsTeamsReposSetOutput };
  /** Take a team's role on a repository away. Takes a team's role on a repository away; its members keep the roles they have otherwise (members of the organization read). Repositories told of the change stop counting it at once; every repository stops within 60 seconds for writes and 5 minutes for reads. Owners only. */
  "orgs.teams.repos.remove": { input: OrgsTeamsReposRemoveInput; output: OrgsTeamsReposRemoveOutput };
  /** Start a chunked pack upload. Starts an upload session for a pack too large for one push request: declare the pack's size and the ref updates it carries, upload the parts, then complete. Needs write access to the repository. `fyrden push --chunked` does all of this. */
  "uploads.create": { input: UploadsCreateInput; output: UploadsCreateOutput };
  /** Get a chunked pack upload. Returns an upload session started by the caller: which parts are stored, and the outcome once complete. */
  "uploads.get": { input: UploadsGetInput; output: UploadsGetOutput };
  /** Complete a chunked pack upload. Assembles the parts, indexes and checks the pack as a push is checked, and applies the ref updates in one transaction. Answers state `indexing` while a large pack is still being indexed: call it again. Must be called with the token that started the session. */
  "uploads.complete": { input: UploadsCompleteInput; output: UploadsCompleteOutput };
  /** Abort a chunked pack upload. Ends an upload session that has not committed and deletes what it stored. */
  "uploads.abort": { input: UploadsAbortInput; output: UploadsAbortOutput };
  /** Import a public git repository. Fetches every branch and tag of a public git repository over HTTPS (smart HTTP, protocol version 2) into this repository, which must be empty, checking the objects as a push is checked. Runs in the background; follow it with the get operation. Needs write access. The source URL must be a public https URL: private and internal addresses and this deployment's own hostnames are refused. */
  "imports.create": { input: ImportsCreateInput; output: ImportsCreateOutput };
  /** Get the repository's import. Returns the progress or outcome of the repository's latest import. */
  "imports.get": { input: ImportsGetInput; output: ImportsGetOutput };
}
